mapper.select:
SELECT id, category_sub_id, name, description, ks_standard, is_active, created_at, updated_at
FROM item
WHERE id = #{id}

SELECT i.id, i.category_sub_id, i.name, i.description, i.ks_standard, i.is_active, i.created_at, i.updated_at
FROM item i
JOIN category_sub cs ON cs.id = i.category_sub_id


        AND i.category_sub_id = #{categorySubId}


        AND cs.category_main_id = #{categoryMainId}


ORDER BY i.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM item i
JOIN category_sub cs ON cs.id = i.category_sub_id


        AND i.category_sub_id = #{categorySubId}


        AND cs.category_main_id = #{categoryMainId}
